import React from 'react';

import { cross } from '../icons';

import ViviIcon from '../ViviIcon';

import './style.scss';

interface Props {
  onRemove: () => void;
  url: string;
}

class VideoCard extends React.Component<Props>
{
  render() {
    const { url } = this.props;

    // remove http:// or https:// then remove www. and trailing slash if present
    const shortUrl = url.replace(/^http(s)?:\/\//, '').replace(/^www./, '').replace(/\/$/, '');

    return (
      <div className="VideoCard">
        <div className="videoPath" title={url}>
          {shortUrl}
        </div>
        <div className="removeCard">
          <button onClick={this.props.onRemove}>
            <ViviIcon icon={cross} size={16} />
          </button>
        </div>
      </div>
    )
  }
}

export default VideoCard;
