import React from 'react';

import { Icon } from '../icons';

interface Props {
  icon: Icon;
  size?: number;
  strokeColor?: string;
}

class ViviIcon extends React.Component<Props> {
  render() {
    const { icon, size, strokeColor } = this.props;
    const finalSize = size ?? 20;

    return (
      <svg width={finalSize} height={finalSize} style={{ fill: 'currentColor', color: strokeColor }} xmlns="http://www.w3.org/2000/svg" xmlnsXlink="http://www.w3.org/1999/xlink">
        <use xlinkHref={`${icon.svg}#icon-${icon.name}`}></use>
      </svg>
    );
  }
}

export default ViviIcon;
