import React from 'react';

import { Icon } from '../icons';
import ViviIcon from '../ViviIcon';

import './style.scss';

interface Props {
  color?: string;
  disabled?: boolean;
  icon: Icon;
  label: string;
  size?: number;
  strokeColor?: string;
  onClick?: () => void;
}

class IconButton extends React.Component<Props> {
  render() {
    const { disabled, icon, label, size, onClick, strokeColor } = this.props;

    return (
      <div className="IconButton">
        <button
          disabled={disabled}
          onClick={onClick}
          style={this._buttonStyle()}
        >
          <ViviIcon icon={icon} size={size || 28} strokeColor={strokeColor} />
        </button>
        <div className={`label ${disabled ? 'disabled' : ''}`}>
          {label}
        </div>
      </div>
    );
  }

  private _buttonStyle = () => {
    const { color } = this.props;
    if (!color) {
      return {};
    }

    return {
      backgroundColor: color
    };
  }
}

export default IconButton;
