import React from 'react';

import './style.scss';

interface Props {
  disabled?: boolean;
  onChange?: (value: string) => void;
  placeholder?: string;
}

class ViviInput extends React.Component<Props> {
  render() {
    const { disabled, onChange, placeholder } = this.props;
    return (
      <input
        className="ViviInput"
        disabled={disabled}
        onChange={(event) => onChange?.(event.target.value)}
        placeholder={placeholder}
        type="text"
      />
    );
  }
}

export default ViviInput;
