import React from 'react';

import Bowser from 'bowser';
import browser from 'webextension-polyfill';

import IconButton from '../IconButton';
import VideoCard from '../VideoCard';
import ViviButton from '../ViviButton';
import ViviIcon from '../ViviIcon';
import ViviInput from '../ViviInput';
import ViviSpinner from '../ViviSpinner';
import { checkedCircle, download, info, link, message, playVideo, plus, screenShare, stop, trashcan } from '../icons';
import { JSONValue, tryParseJson } from '../util/json';

import './style.scss';

const reconnectDelay = 5_000;
const socketAddress = 'ws://localhost:12804/extension';
const videoLimit = 50;

interface State {
  clientAuthenticated: boolean;
  clientCanLink: boolean;
  clientCanMessage: boolean;
  clientCanShare: boolean;
  clientCanStop: boolean;
  clientCanVideo: boolean;
  clientConnected: boolean;
  clientHasMessage: boolean;
  clientRoomName: string;
  inFlight: boolean;
  inFlightCommand?: string;
  inFlightFailed: boolean;
  playlistName: string;
  queue: string[];
  socketStatus: 'connecting' | 'connected' | 'disconnected';
  tabId?: number;
  tabUrl?: string;
  tabUrlValid: 'pending' | 'valid' | 'invalid' | 'unknown';
}

class App extends React.Component<{}, State> {
  private socket?: WebSocket;
  private linkPrefix: string = 'https://use.vivi.io';
  private isSupported: boolean = false;

  constructor(props: {}) {
    super(props);

    const queue = tryParseJson(localStorage.getItem('queue'), []);

    this.state = {
      clientAuthenticated: true,
      clientCanLink: true,
      clientCanMessage: true,
      clientCanShare: true,
      clientCanStop: true,
      clientCanVideo: true,
      clientConnected: true,
      clientHasMessage: true,
      clientRoomName: '',
      inFlight: false,
      inFlightFailed: false,
      playlistName: '',
      queue,
      socketStatus: 'connecting',
      tabUrlValid: 'invalid'
    };

    this.handleUpdated = this.handleUpdated.bind(this);
  }

  async componentDidMount() {
    const bowser = Bowser.parse(window.navigator.userAgent);
    console.log('bowser', bowser);
    const isDesktop = bowser.platform.type === 'desktop';
    if (isDesktop) {
      this.linkPrefix = 'vivi:';
    }
    this.isSupported = isDesktop && ['Chrome', 'Edge'].includes(bowser.browser.name ?? '');

    // get current URL
    browser.tabs.query({ active: true, currentWindow: true }).then(([activeTab]) => {
      const { id, url } = activeTab;
      if (url) {
        this.setState({
          tabId: id,
          tabUrl: url,
          tabUrlValid: 'pending'
        });

        this.validateUrl(url);
      } else {
        this.setState({
          tabId: id,
          tabUrl: undefined
        });
      }

      // listen for changes to URL
      // we only get the first change with the `activeTab` permission, need `tabs` for all
      browser.tabs.onUpdated.addListener(this.handleUpdated);
    });

    this.connect();
  }

  connect() {
    try {
      console.log('socket open');
      this.socket = new WebSocket(socketAddress);

      this.socket.addEventListener('close', ({ code, reason }) => {
        console.log('socket close', { code, reason });

        this.socket = undefined;

        this.setState({
          socketStatus: 'disconnected'
        });

        setTimeout(() => this.connect(), reconnectDelay);
      });

      this.socket.addEventListener('error', () => {
        console.warn('socket error');
      });

      this.socket.addEventListener('message', ({ data }) => {
        try {
          console.debug('socket message', { data });
          const json = JSON.parse(data);
          const { version, command, success } = json;
          if (version === 1 && this.state.inFlight && command === this.state.inFlightCommand) {
            if (success) {
              console.log('command succeeded', { ...json });
              if (['play', 'playlist'].includes(command)) {
                this.clearQueue();
              }
              window.close();
            } else {
              console.warn('command failed', { ...json });
              this.setState({
                inFlightFailed: true
              });
            }

            this.setState({
              inFlight: false,
              inFlightCommand: undefined
            });
          } else if (version === 1 && command === 'state') {
            const { authenticated, canLink, canMessage, canShare, canStop, canVideo, connected, hasMessage, roomName } = json.state;
            this.setState({
              clientAuthenticated: authenticated,
              clientCanLink: canLink,
              clientCanMessage: canMessage,
              clientCanShare: canShare,
              clientCanStop: canStop,
              clientCanVideo: canVideo,
              clientConnected: connected,
              clientHasMessage: hasMessage,
              clientRoomName: roomName
            });
          }
        } catch (error) {
          console.warn('failed to parse message as JSON', { data, error });
        }
      });

      this.socket.addEventListener('open', () => {
        console.log('socket open');

        this.setState({
          clientAuthenticated: true,
          clientCanLink: true,
          clientCanMessage: true,
          clientCanShare: true,
          clientCanStop: true,
          clientCanVideo: true,
          clientConnected: true,
          clientHasMessage: true,
          clientRoomName: '',
          socketStatus: 'connected'
        });
      });
    } catch (error) {
      console.warn('socket error', { error });

      this.socket = undefined;

      this.setState({
        socketStatus: 'disconnected'
      });

      setTimeout(() => this.connect(), reconnectDelay);
    }
  }

  sendMessage(json: JSONValue) {
    if (this.socket) {
      this.socket.send(JSON.stringify(json));
    }
  }

  handleUpdated(tabId: number, { url }: browser.tabs._OnUpdatedChangeInfo, tab: browser.tabs.Tab) {
    if (tabId === this.state.tabId && url) {
      this.setState({
        tabUrl: url,
        tabUrlValid: 'pending'
      });

      this.validateUrl(url);
    }
  }

  async validateUrl(url: string) {
    const { hostname, protocol } = new URL(url);

    if (!['http:', 'https:'].includes(protocol) || ['online.clickview.com.au'].includes(hostname)) {
      this.setState({
        tabUrlValid: 'invalid'
      });
      return;
    }

    const valid = await this.processUrl(url);

    if (url !== this.state.tabUrl) {
      // tab changed while we were waiting, drop it
      return;
    }

    this.setState({
      tabUrlValid: valid ? 'valid' : 'unknown'
    });
  }

  async processUrl(url: string): Promise<boolean> {
    try {
      const response = await fetch('https://api.vivi.io/ytdl/process', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({ url })
      });
      return response.ok;
    } catch (error) {
      return false;
    }
  }

  shareLink() {
    const { tabUrl } = this.state;

    if (!tabUrl) {
      return;
    }

    if (this.state.socketStatus === 'connected') {
      this.sendMessage({
        command: 'link',
        url: tabUrl,
        version: 1
      });

      this.setState({
        inFlight: true,
        inFlightCommand: 'link',
        inFlightFailed: false
      });
    } else {
      browser.tabs.create({ url: `${this.linkPrefix}/link?url=${encodeURIComponent(tabUrl)}` });
    }
  }

  shareMessage() {
    const { tabUrl } = this.state;

    if (!tabUrl) {
      return;
    }

    if (this.state.socketStatus === 'connected') {
      this.sendMessage({
        command: 'message',
        message: tabUrl,
        version: 1
      });

      this.setState({
        inFlight: true,
        inFlightCommand: 'message',
        inFlightFailed: false
      });
    } else {
      browser.tabs.create({ url: `${this.linkPrefix}/message?message=${encodeURIComponent(tabUrl)}` });
    }
  }

  stop() {
    if (this.state.socketStatus === 'connected') {
      this.sendMessage({
        command: 'stop',
        version: 1
      });

      this.setState({
        inFlight: true,
        inFlightCommand: 'stop',
        inFlightFailed: false
      });
    } else {
      browser.tabs.create({ url: `${this.linkPrefix}/stop` });
    }
  }

  shareScreen() {
    if (this.state.socketStatus === 'connected') {
      this.sendMessage({
        command: 'share',
        version: 1
      });

      this.setState({
        inFlight: true,
        inFlightCommand: 'share',
        inFlightFailed: false
      });
    } else {
      browser.tabs.create({ url: `${this.linkPrefix}/share` });
    }
  }

  playQueue() {
    const { queue } = this.state;

    if (queue.length === 0) {
      return;
    }

    if (this.state.socketStatus === 'connected') {
      this.sendMessage({
        command: 'play',
        urls: queue,
        version: 1
      });

      this.setState({
        inFlight: true,
        inFlightCommand: 'play',
        inFlightFailed: false
      });
    } else {
      browser.tabs.create({ url: `${this.linkPrefix}/play?${queue.map((url) => `url=${encodeURIComponent(url)}`).join('&')}` });
    }
  }

  playVideo() {
    const { tabUrl } = this.state;

    if (!tabUrl) {
      return;
    }

    if (this.state.socketStatus === 'connected') {
      this.sendMessage({
        command: 'play',
        urls: [tabUrl],
        version: 1
      });

      this.setState({
        inFlight: true,
        inFlightCommand: 'play',
        inFlightFailed: false
      });
    } else {
      browser.tabs.create({ url: `${this.linkPrefix}/play?url=${encodeURIComponent(tabUrl)}` });
    }
  }

  addVideo() {
    const { tabUrl } = this.state;

    if (!tabUrl) {
      return;
    }

    const queue = [...this.state.queue, tabUrl];
    this.setQueue(queue);
  }

  removeVideo(index: number) {
    const queue = this.state.queue.slice();
    queue.splice(index, 1);
    this.setQueue(queue);
  }

  clearQueue() {
    this.setQueue([]);
  }

  setQueue(queue: string[]) {
    this.setState({
      queue
    });

    localStorage.setItem('queue', JSON.stringify(queue));
  }

  savePlaylist() {
    const { playlistName, queue } = this.state;

    if (!playlistName.trim() || queue.length === 0) {
      return;
    }

    if (this.state.socketStatus === 'connected') {
      this.sendMessage({
        command: 'playlist',
        name: playlistName,
        urls: queue,
        version: 1
      });

      this.setState({
        inFlight: true,
        inFlightCommand: 'playlist',
        inFlightFailed: false
      });
    } else {
      browser.tabs.create({ url: `${this.linkPrefix}/playlist?name=${encodeURIComponent(playlistName)}&${queue.map((url) => `url=${encodeURIComponent(url)}`).join('&')}` });
    }
  }

  render() {
    const { clientAuthenticated, clientCanLink, clientCanMessage, clientCanShare, clientCanStop, clientCanVideo, clientConnected, clientHasMessage, inFlight, inFlightFailed, playlistName, queue, socketStatus, tabUrl, tabUrlValid } = this.state;
    const socketConnected = socketStatus === 'connected';
    const noUrl = !tabUrl;
    const noVideo = !tabUrl || tabUrlValid === 'invalid';

    return (
      <>
        <div className="Status">
          {this.renderVideoAlert()}
        </div>

        {inFlightFailed && <div className="FailedStatus">Something went wrong, please check the Vivi App</div>}

        <div className="App">
          <div className="connection">
            {this.renderConnectionStatus()}
          </div>
          <div className="buttons">
            <div className="row">
              <div className="button">
                <IconButton
                  color="#0082fa"
                  disabled={inFlight || (clientConnected && !clientCanStop)}
                  icon={stop}
                  label="Stop"
                  onClick={() => this.stop()}
                />
              </div>

              <div className="button">
                <IconButton
                  color="#1171e9"
                  disabled={inFlight || (clientConnected && !clientCanShare)}
                  icon={screenShare}
                  label="Share Screen"
                  onClick={() => this.shareScreen()}
                />
              </div>

              {clientHasMessage ? (
                <div className="button">
                  <IconButton
                    color="#226286"
                    disabled={inFlight || (clientConnected && !clientCanMessage) || noUrl}
                    icon={message}
                    label="Share Link"
                    onClick={() => this.shareMessage()}
                  />
                </div>
              ) : (
                <div className="button">
                  <IconButton
                    color="#6e50b9"
                    disabled={inFlight || (clientConnected && !clientCanLink) || noUrl}
                    icon={link}
                    label="Share Link"
                    onClick={() => this.shareLink()}
                  />
                </div>
              )}
            </div>
            <div className="row">
              {queue.length > 0
                ? (
                  <div className="button">
                    <IconButton
                      color="#be4b8a"
                      disabled={inFlight || (clientConnected && !clientCanVideo)}
                      icon={playVideo}
                      label="Play Queue"
                      onClick={() => this.playQueue()}
                    />
                  </div>
                )
                : (
                  <div className="button">
                    <IconButton
                      color="#be4b8a"
                      disabled={inFlight || (clientConnected && !clientCanVideo) || noVideo}
                      icon={playVideo}
                      label="Play Video"
                      onClick={() => this.playVideo()}
                    />
                  </div>
                )
              }

              <div className="button">
                <IconButton
                  color="#fff"
                  disabled={inFlight || noVideo || queue.length >= videoLimit}
                  icon={plus}
                  label="Add Video to Queue"
                  onClick={() => this.addVideo()}
                  strokeColor="#000"
                />
              </div>
            </div>
          </div>

          {queue.length > 0 && (
            <div className="playlist">
              <div className="name">
                <ViviInput
                  onChange={(value) => this.setState({ playlistName: value })}
                  placeholder="Playlist Name"
                />
              </div>
              <div className="actions">
                <div className="action">
                  <ViviButton
                    disabled={inFlight || (socketConnected && !clientAuthenticated) || !playlistName.trim()}
                    icon={download}
                    onClick={() => this.savePlaylist()}
                  >
                    Save Playlist
                  </ViviButton>
                </div>
                <div className="action">
                  <ViviButton
                    disabled={inFlight}
                    icon={trashcan}
                    onClick={() => this.clearQueue()}
                  >
                    Clear Queue
                  </ViviButton>
                </div>
              </div>
              <div className="queue">
                {queue.map((url, index) => (
                  <div className="video" key={index}>
                    <VideoCard
                      onRemove={() => this.removeVideo(index)}
                      url={url}
                    />
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      </>
    );
  }

  renderConnectionStatus() {
    const { clientAuthenticated, clientConnected, clientRoomName, socketStatus } = this.state;
    if (socketStatus === 'connecting') {
      return (
        <div className="status">
          Connecting to the Vivi App...
        </div>
      );
    } else if (socketStatus === 'disconnected') {
      if (this.isSupported) {
        return (
          <div className="status">
            The Vivi App isn't running: <a href={`${this.linkPrefix}/`} target="_blank" rel="noopener noreferrer">Open</a> or <a href="https://get.vivi.io" target="_blank" rel="noopener noreferrer">Install</a>
          </div>
        );
      } else {
        return (
          <div className="status">
            Your browser has Beta support only
          </div>
        );
      }
    } else if (!clientAuthenticated) {
      return (
        <div className="status">
          The Vivi App isn't signed in
        </div>
      );
    } else if (!clientConnected) {
      return (
        <div className="status">
          The Vivi App isn't connected to a room
        </div>
      );
    } else {
      return (
        <div className="status">
          Connected to: {clientRoomName}
        </div>
      );
    }
  }

  renderVideoAlert() {
    // otherwise, show video status
    const { tabUrl, tabUrlValid } = this.state;
    if (tabUrl) {
      if (tabUrlValid === 'pending') {
        return (
          <div className="bar">
            <div className="icon">
              <ViviSpinner />
            </div>
            <span>
              Checking video...
            </span>
          </div>
        );
      } else if (tabUrlValid === 'invalid') {
        return (
          <div className="bar">
            <div className="icon">
              <ViviIcon icon={info} size={20} />
            </div>
            <span>
              This video can't be played with Video Direct
            </span>
          </div>
        );
      } else if (tabUrlValid === 'unknown') {
        return (
          <div className="bar">
            <div className="icon">
              <ViviIcon icon={info} size={20} />
            </div>
            <span>
              This video might not be playable with Video Direct
            </span>
          </div>
        );
      } else if (tabUrlValid === 'valid') {
        return (
          <div className="bar">
            <div className="icon">
              <ViviIcon icon={checkedCircle} size={20} />
            </div>
            <span>
              This video can be played with Video Direct
            </span>
          </div>
        );
      }
    }
  }
}

export default App;
