import React from 'react';

import { Icon } from '../icons';
import ViviIcon from '../ViviIcon';

import './style.scss';

interface Props {
  disabled?: boolean;
  icon: Icon;
  onClick: () => void;
}

class ViviButton extends React.Component<Props> {
  render() {
    return (
      <button className="ViviButton" disabled={this.props.disabled ?? false} onClick={this.props.onClick}>
        <ViviIcon icon={this.props.icon} size={14}/>
        {this.props.children}
      </button>
    );
  }
}

export default ViviButton;
